{
  "steps": [
    {
      "step_id": 1,
      "time": "08:00",
      "role": "企业负责人",
      "action": "先期处置",
      "description": "操作工在储罐区操作时发现二氧化碳阀门泄漏，立即向班组长和车间主任报告；车间主任同时向安全科和公司主要负责人报告事故情况。企业负责人接报后立即组织现场先期处置，关闭相关阀门、停止作业，并通知各应急小组集结待命。",
      "resources": []
    },
    {
      "step_id": 2,
      "time": "08:02",
      "role": "企业负责人",
      "action": "事故上报",
      "description": "企业负责人向属地应急管理部门、生态环境部门报告危化品泄漏事故情况，包括泄漏物质、泄漏位置、影响范围、人员伤亡等初步信息。",
      "resources": [
        {
          "resource_type": "卫星电话",
          "quantity": 1
        }
      ]
    },
    {
      "step_id": 3,
      "time": "08:03",
      "role": "企业负责人",
      "action": "启动响应",
      "description": "企业负责人宣布启动危险化学品泄漏事故应急预案，成立现场应急指挥部，组织各工作组到位，按照各自职责准备展开工作。",
      "resources": []
    },
    {
      "step_id": 4,
      "time": "08:05",
      "role": "企业负责人",
      "action": "关停设施",
      "description": "企业负责人下令关停储罐区相关进料阀门、切断物料来源，停止周边一切生产作业，防止泄漏扩大。",
      "resources": []
    },
    {
      "step_id": 5,
      "time": "08:05",
      "role": "现场警戒组",
      "action": "人员疏散",
      "description": "现场警戒组组织储罐区及周边无关人员按照预定疏散路线撤离至安全集合点，清点人数，确保人员安全。",
      "resources": []
    },
    {
      "step_id": 6,
      "time": "08:06",
      "role": "企业负责人",
      "action": "物资转移",
      "description": "企业负责人组织人员将泄漏区域周边可转移的危险化学品物资转运至安全区域，减少事故扩大风险。",
