        {
          "resource_type": "运输车辆",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 7,
      "time": "08:08",
      "role": "应急指挥部",
      "action": "启动响应",
      "description": "区政府接报后启动区级危险化学品事故应急预案，成立现场应急指挥部，统一指挥协调各救援组行动。总指挥负责现场全面指挥，下达处理方案，命令并指挥实施。",
      "resources": [
        {
          "resource_type": "消防车",
          "quantity": 2
        },
        {
          "resource_type": "救护车",
          "quantity": 1
        }
      ]
    },
    {
      "step_id": 8,
      "time": "08:08",
      "role": "应急指挥部",
      "action": "统一指挥",
      "description": "应急指挥部统一指挥各工作组按照职责展开救援行动，副总指挥协助总指挥协调各工作组行动。",
      "resources": []
    },
    {
      "step_id": 9,
      "time": "08:10",
      "role": "应急指挥部",
      "action": "应急队伍集结",
      "description": "应急指挥部调集消防救援队伍、医疗救护组、治安警戒组、环境监测组等应急队伍集结到位，按照各自职责准备展开工作。",
      "resources": [
        {
          "resource_type": "消防车",
          "quantity": 2
        },
        {
          "resource_type": "救护车",
          "quantity": 1
        },
        {
          "resource_type": "防化装备",
          "quantity": 10
        }
      ]
    },
    {
      "step_id": 10,
      "time": "08:10",
      "role": "应急指挥部",
      "action": "信息通报",
      "description": "应急指挥部向市应急局、市生态环境局等上级部门通报事故情况，请求支援和指导。",
      "resources": []
    },
    {
      "step_id": 11,
      "time": "08:12",
      "role": "危险源控制及救援排险组",
      "action": "个人防护",
      "description": "危险源控制及救援排险组救援人员穿戴防化服、正压式空气呼吸器等个人防护装备，做好进入泄漏危险区域的准备。",
      "resources": [
        {
          "resource_type": "防化装备",
          "quantity": 6
        }
      ]
    },
    {
      "step_id": 12,
      "time": "08:13",
      "role": "现场警戒组",
      "action": "现场警戒",
      "description": "专职安全员带救援人员赶到现场后拉好警示线，设置警戒区域，防止无关人员靠近。现场警戒组负责维护现场治安秩序，设置警戒带、警示标志，禁止无关人员和车辆进入。",
      "resources": []
    },
    {
      "step_id": 13,
      "time": "08:13",
      "role": "现场警戒组",
      "action": "危险区划定",
      "description": "现场警戒组根据泄漏物质特性和气象条件，划定热区（危险区）、温区（缓冲区）、冷区（安全区），设置明显标识，实施分区管控。",
      "resources": []
    },
    {
      "step_id": 14,
      "time": "08:14",
      "role": "交通管制组",
      "action": "交通管制",
      "description": "交通管制组对事故现场周边道路实施交通管制，设置警戒线和交通引导标志，疏导过往车辆和行人绕行，保障救援通道畅通。",
      "resources": []
    },
    {
      "step_id": 15,
      "time": "08:15",
      "role": "危险源控制及救援排险组",
      "action": "进入危区",
      "description": "危险源控制及救援排险组救援人员穿戴好个人防护装备后进入泄漏危险区域，开展现场侦检和泄漏控制作业。",
      "resources": [
        {
          "resource_type": "防化装备",
          "quantity": 6
        }
      ]
    },
    {
      "step_id": 16,
      "time": "08:15",
      "role": "危险源控制及救援排险组",
      "action": "现场侦检",
      "description": "危险源控制及救援排险组使用检测设备对泄漏区域进行现场侦检，确定泄漏物质种类、浓度、扩散范围，为后续处置提供依据。",
      "resources": [
        {
          "resource_type": "环境监测设备",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 17,
      "time": "08:17",
      "role": "危险源控制及救援排险组",
      "action": "污染源切断",
      "description": "危险源控制及救援排险组开启备用阀门，切断泄漏源，关闭相关阀门和进料管线，阻止危化品继续泄漏。",
      "resources": []
    },
    {
      "step_id": 18,
      "time": "08:20",
      "role": "危险源控制及救援排险组",
      "action": "泄漏控制",
      "description": "危险源控制及救援排险组采取堵漏、围堵等措施控制泄漏，使用围油栏等设备防止泄漏物扩散，救援人员手持灭火器随时防止发生火情。",
      "resources": [
        {
          "resource_type": "围油栏",
          "quantity": 4
        },
        {
          "resource_type": "消防车",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 19,
      "time": "08:20",
      "role": "消防救援组",
      "action": "灭火处置",
      "description": "消防救援组部署消防车和灭火器材，对泄漏区域进行喷雾稀释和冷却保护，随时准备扑救可能发生的火灾。",
      "resources": [
        {
          "resource_type": "消防车",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 20,
      "time": "08:18",
      "role": "疏散引导组",
      "action": "周边疏散",
      "description": "疏散引导组组织事故现场周边可能受影响区域的群众进行疏散，按照预定路线引导至安全安置点。",
      "resources": []
    },
    {
      "step_id": 21,
      "time": "08:22",
      "role": "疏散引导组",
      "action": "安置救助",
      "description": "疏散引导组在安全区域设置临时安置点，搭建帐篷，对疏散群众进行安置和救助，提供必要的生活保障。",
      "resources": [
        {
          "resource_type": "帐篷",
          "quantity": 5
        }
      ]
    },
    {
      "step_id": 22,
      "time": "08:22",
      "role": "医疗救护组",
      "action": "救护设点",
      "description": "医疗救护组在安全区域设立医疗救护点，配备急救包和救护车，做好救治伤员的准备。",
      "resources": [
        {
          "resource_type": "急救包",
          "quantity": 5
        },
        {
          "resource_type": "救护车",
          "quantity": 1
        }
      ]
    },
    {
      "step_id": 23,
      "time": "08:23",
      "role": "医疗救护组",
      "action": "医疗救护",
      "description": "医疗救护组对现场中毒和受伤人员进行紧急医疗救治，必要时进行现场急救处理后转运至医院。",
      "resources": [
        {
          "resource_type": "急救包",
          "quantity": 5
        },
        {
          "resource_type": "救护车",
          "quantity": 1
        }
      ]
    },
    {
      "step_id": 24,
      "time": "08:24",
      "role": "医疗救护组",
      "action": "伤员转运",
      "description": "医疗救护组将中毒和受伤人员使用救护车转运至就近医院进行进一步治疗。",
      "resources": [
        {
          "resource_type": "救护车",
          "quantity": 1
        }
      ]
    },
    {
      "step_id": 25,
      "time": "08:25",
      "role": "环境监测组",
      "action": "环境监测",
      "description": "环境监测组使用环境监测设备对泄漏区域及周边大气、水体、土壤进行环境监测，实时掌握污染物浓度和扩散趋势。",
      "resources": [
        {
          "resource_type": "环境监测设备",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 26,
      "time": "08:25",
      "role": "气象/监测组",
      "action": "气象监测",
      "description": "气象/监测组对事故现场风向、风速、温度等气象条件进行监测，为泄漏物扩散预测和人员疏散提供气象依据。",
      "resources": []
    },
    {
      "step_id": 27,
      "time": "08:26",
      "role": "气象/监测组",
      "action": "扩散预测",
      "description": "气象/监测组根据气象监测数据和泄漏物质特性，对有毒有害气体的扩散方向和范围进行预测，为指挥部决策提供技术支持。",
      "resources": [
        {
          "resource_type": "无人机",
          "quantity": 1
        }
      ]
    },
    {
      "step_id": 28,
      "time": "08:28",
      "role": "防化处置组",
      "action": "防化洗消",
      "description": "防化处置组对进入危险区域的救援人员进行洗消作业，使用洗消药剂对人员、装备进行清洗消毒，防止污染物扩散。",
      "resources": [
        {
          "resource_type": "洗消药剂",
          "quantity": 10
        }
      ]
    },
    {
      "step_id": 29,
      "time": "08:30",
      "role": "防化处置组",
      "action": "污染洗消",
      "description": "防化处置组对泄漏区域地面、设备设施进行洗消作业，使用洗消药剂对污染区域进行清洗消毒，消除污染危害。",
      "resources": [
        {
          "resource_type": "洗消药剂",
          "quantity": 10
        }
      ]
    },
    {
      "step_id": 30,
      "time": "08:30",
      "role": "防化处置组",
      "action": "防化洗消",
      "description": "防化处置组组织开展全面洗消作业，对事故现场及周边受污染区域进行彻底清洗消毒，确保环境安全。",
