      "action": "达标确认",
      "description": "环境监测组确认处理后的污水各项指标达到排放标准，水质合格。",
      "resources": [
        {
          "resource_type": "环境监测设备",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 35,
      "time": "08:40",
      "role": "防化处置组",
      "action": "污水排放",
      "description": "防化处置组在确认污水达标后，按照环保要求进行达标排放。",
      "resources": []
    },
    {
      "step_id": 36,
      "time": "08:42",
      "role": "环境监测组",
      "action": "环境监测",
      "description": "环境监测组对事故现场及周边环境进行复测，监测大气、水体、土壤中污染物浓度是否恢复正常水平。",
      "resources": [
        {
          "resource_type": "环境监测设备",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 37,
      "time": "08:45",
      "role": "环境监测组",
      "action": "环境合格",
      "description": "环境监测组确认事故现场及周边环境各项指标均已恢复正常，环境质量合格，具备解除警戒条件。",
      "resources": [
        {
          "resource_type": "环境监测设备",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 38,
      "time": "08:46",
      "role": "现场指挥部",
      "action": "危害消除",
      "description": "现场指挥部确认泄漏源已完全控制、污染物已消除、环境监测合格，事故危害已消除。",
      "resources": []
    },
    {
      "step_id": 39,
      "time": "08:47",
      "role": "现场警戒组",
      "action": "撤除警戒",
      "description": "现场警戒组在确认环境合格后撤除现场警戒线，恢复交通和正常秩序。",
      "resources": []
    },
    {
      "step_id": 40,
      "time": "08:48",
      "role": "应急指挥部",
      "action": "响应终止",
      "description": "应急指挥部宣布终止应急响应，各救援组有序撤离现场。",
      "resources": []
    },
    {
      "step_id": 41,
      "time": "08:50",
      "role": "区政府",
      "action": "善后处置",
      "description": "救援人员对现场进行清理，区政府组织开展善后处置工作，包括事故调查、损失评估、环境恢复、群众安抚等。",
      "resources": []
    },
    {
      "step_id": 42,
      "time": "09:00",
      "role": "应急指挥部",
      "action": "总结评估",
      "description": "公司总经理对演练过程进行点评，总结演练经验，评估应急处置效果，提出改进意见。",
      "resources": []
    }
  ]
}

